  // Custom theme or transparent check
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Timings mapped to dynamic percentages of total animation duration
  const hoverFrame = Math.floor(0.15 * durationInFrames);
  const startDragFrame = Math.floor(0.20 * durationInFrames);
  const arriveTargetFrame = Math.floor(0.35 * durationInFrames);
  const releaseFrame = Math.floor(0.38 * durationInFrames);
  const popupStartFrame = Math.floor(0.42 * durationInFrames);
  const popupFullFrame = Math.floor(0.46 * durationInFrames);
  const loadEndFrame = Math.floor(0.75 * durationInFrames);
  const successStartFrame = Math.floor(0.78 * durationInFrames);

  // Core Visual Elements Layout Coordinate mapping
  const folderSize = Math.min(internalWidth, internalHeight) * 0.082;
