  const targetX = internalWidth * 0.16;
  const targetY = internalHeight * 0.15;

  // 1. Mouse Drag Coordinates Interpolation
  let mouseX = startX;
  let mouseY = startY;

  if (frame < hoverFrame) {
    // Phase A: Mouse moves to folder
    mouseX = interpolate(frame, [0, hoverFrame], [startX, folderX + folderSize * 0.6], {
      extrapolateRight: "clamp",
    });
    mouseY = interpolate(frame, [0, hoverFrame], [startY, folderY + folderSize * 0.6], {
      extrapolateRight: "clamp",
    });
  } else if (frame < startDragFrame) {
    // Phase B: Pause slightly over folder
    mouseX = folderX + folderSize * 0.6;
    mouseY = folderY + folderSize * 0.6;
  } else if (frame < arriveTargetFrame) {
    // Phase C: Drag folder to Target Icon
    mouseX = interpolate(frame, [startDragFrame, arriveTargetFrame], [folderX + folderSize * 0.6, targetX + folderSize * 0.6], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
    mouseY = interpolate(frame, [startDragFrame, arriveTargetFrame], [folderY + folderSize * 0.6, targetY + folderSize * 0.6], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
  } else if (frame < releaseFrame) {
    // Phase D: Hold over target before releasing
    mouseX = targetX + folderSize * 0.6;
    mouseY = targetY + folderSize * 0.6;
  } else {
    // Phase E: Rest cursor slightly offset to the side
    mouseX = interpolate(frame, [releaseFrame, releaseFrame + 15], [targetX + folderSize * 0.6, targetX + folderSize * 1.5], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
    mouseY = interpolate(frame, [releaseFrame, releaseFrame + 15], [targetY + folderSize * 0.6, targetY + folderSize * 1.2], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });
  }

